-- Backup generated on 2026-10-25 20:32:56

CREATE OR REPLACE FUNCTION public.fn_dev_login(p_email character varying DEFAULT NULL::character varying)  RETURNS TABLE(out_status character varying, out_user_id uuid, out_tenant_id uuid, out_effective_tenant_id uuid, out_active_org_id uuid, out_email character varying, out_display_name character varying)  LANGUAGE plpgsql AS $function$ DECLARE     v_target_email VARCHAR; BEGIN     IF p_email IS NOT NULL AND TRIM(p_email) <> '' THEN         SELECT email INTO v_target_email          FROM users          WHERE LOWER(email) = LOWER(TRIM(p_email)) OR normalized_email = UPPER(TRIM(p_email))          LIMIT 1;     END IF;      IF v_target_email IS NULL THEN         SELECT email INTO v_target_email          FROM users          WHERE normalized_email = 'PRIYA@LITTLESTARS.COM'          LIMIT 1;     END IF;      IF v_target_email IS NULL THEN         SELECT email INTO v_target_email          FROM users          ORDER BY created_at ASC          LIMIT 1;     END IF;      IF v_target_email IS NULL THEN         RETURN QUERY SELECT 'no_users'::VARCHAR, NULL::UUID, NULL::UUID, NULL::UUID, NULL::UUID, NULL::VARCHAR, NULL::VARCHAR;         RETURN;     END IF;      RETURN QUERY      SELECT * FROM fn_sync_external_login('DevLogin', v_target_email, v_target_email, 'Dev', 'User', NULL, 'Daycare'); END; $function$ ;
